package server

import (
	"fmt"
	"log/slog"
	"net/http"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/r0si/sovereign/internal/db"
	"github.com/r0si/sovereign/internal/server/middleware"
)

// TaskStatusPendingApproval marks tasks that were generated by the AI assistant
// and must be explicitly approved by an operator before the agent executes them.
const approvalExpiredError = "approval expired without a second operator"
// Beacon task claim only picks up tasks with status "pending", so these tasks
// stay dormant until an operator approves them.
const TaskStatusPendingApproval = "pending_approval"

// postTaskApprovalChat writes an approval card to the task's agent
// engagement. Chat is best-effort: a broken chat table must never undo an
// approval or rejection that already committed.
func (s *Server) postTaskApprovalChat(task db.Task, kind, text, metadata string) {
	var agent db.Implant
	if err := s.db.Select("tenant_id, engagement_id").Where("id = ?", task.AgentID).First(&agent).Error; err != nil {
		return
	}
	if agent.EngagementID == nil || *agent.EngagementID == 0 {
		return
	}
	taskID := task.ID
	if err := s.postSystemChatToTenant(agent.TenantID, *agent.EngagementID, kind, text, &taskID, metadata); err != nil {
		slog.Warn("Task approval chat card failed", "task_id", task.ID, "err", err)
		s.LogAuditRecord(nil, "chat_system_message_failed", "agent", task.AgentID,
			fmt.Sprintf("task #%d: %v", task.ID, err), false, err)
	}
}

// handleApproveTask promotes a pending_approval task to "pending" so the beacon
// can claim and execute it.
// POST /tasks/:taskId/approve
func (s *Server) handleApproveTask(c *gin.Context) {
	if !s.requireOperator(c) {
		return
	}

	var taskID uint
	if _, err := fmt.Sscanf(c.Param("taskId"), "%d", &taskID); err != nil {
		respondError(c, http.StatusBadRequest, "invalid task id")
		return
	}

	// Tenant gate (agent-visibility): tasks carry no reliable TenantID, so a
	// foreign-tenant pending task must 404 here instead of being approvable.
	task, ok := s.findVisibleTask(c, taskID)
	if !ok {
		return
	}
	if task.Status != TaskStatusPendingApproval {
		respondError(c, http.StatusBadRequest, fmt.Sprintf("task is %s, cannot approve", task.Status))
		return
	}
	if task.CredentialID != nil {
		if !middleware.HasPermission(c, db.PermCredsRead) {
			respondError(c, http.StatusForbidden, "credentials.read is required to approve a credential-referenced task")
			return
		}
		if err := validateCredentialSnapshot(s.db, *task); err != nil {
			s.failCredentialSnapshot(*task)
			respondError(c, http.StatusConflict, errCredentialSnapshot.Error())
			return
		}
	}

	// Two-man rule: the operator that created a dangerous task may not be
	// the one approving it. AI/automation/system-created tasks have no
	// human creator and may be approved by any operator.
	approver := s.currentUsername(c)
	if task.CreatedBy != "" && task.CreatedBy != "ai" && task.CreatedBy != "automation" && task.CreatedBy != "system" && approver != "" && task.CreatedBy == approver {
		respondError(c, http.StatusForbidden, "cannot approve your own task (two-man rule)")
		return
	}

	updates := map[string]interface{}{
		"status":      "pending",
		"approved_by": approver,
		"approved_at": time.Now(),
		"approval_expires_at": nil,
	}
	// Conditional flip, mirroring handleRejectTask/handleCancelTask: a stale
	// read here let approve resurrect a task another operator had just
	// rejected or cancelled (dangerous types would then execute).
	// Expiry is enforced in the WHERE clause, not only by the 5-minute sweep:
	// between the moment a prompt expires and the next sweep, an expired approval was
	// still approvable - which defeats the reason the window exists (the world changed
	// since creation, so a stale prompt must not be confirmable).
	now := time.Now()
	res := s.db.Model(&db.Task{}).
		Where("id = ? AND agent_id = ? AND status IN ?", taskID, task.AgentID, []string{TaskStatusPendingApproval}).
		Where("(approval_expires_at IS NULL OR approval_expires_at > ?)", now).
		Updates(updates)
	if res.Error != nil {
		slog.Error("Failed to approve task", "task", taskID, "err", res.Error)
		respondError(c, http.StatusInternalServerError, "failed to approve task")
		return
	}
	if res.RowsAffected == 0 {
		// Tell the operator WHICH refusal this is: an expired prompt needs a new task,
		// a concurrent rejection needs a conversation.
		if expired, ok := s.maybeCancelExpiredApproval(taskID, now); ok {
			s.LogAuditRecord(c, "approve_task_expired", "agent_id", task.AgentID,
				fmt.Sprintf("Task #%d (%s) approval window had expired", taskID, task.Type), false, nil)
			s.broadcastTaskUpdate(expired.AgentID, expired)
			respondError(c, http.StatusGone, "approval expired; create a new task")
			return
		}
		respondError(c, http.StatusConflict, "task is no longer awaiting approval")
		return
	}
	task.ApprovedAt = &now
	task.ApprovedBy = approver

	slog.Info("Task approved", "agent_id", task.AgentID, "task", taskID, "type", task.Type)
	s.LogAuditRecord(c, "approve_task", "agent_id", task.AgentID,
		fmt.Sprintf("Approved task #%d (%s) [created_by=%s approved_by=%s args=%s]",
			taskID, task.Type, task.CreatedBy, approver, taskArgsHash(task)), true, nil)
	s.broadcastTaskUpdate(task.AgentID, *task)
	s.postTaskApprovalChat(*task, "approval",
		fmt.Sprintf("Task #%d (%s) on %s approved by %s", task.ID, task.Type, task.AgentID, approver),
		fmt.Sprintf(`{"task_id":%d,"type":%q,"status":"approved"}`, task.ID, task.Type))
	respond(c, gin.H{"message": "Task approved and queued for execution"})
}

// maybeCancelExpiredApproval reports whether the task was sitting in
// pending_approval with an expiry in the past, and cancels it the same way the
// sweeper does so a second approve attempt cannot resurrect it. The returned task
// carries the agent id the caller needs for the broadcast.
func (s *Server) maybeCancelExpiredApproval(taskID uint, now time.Time) (db.Task, bool) {
	var task db.Task
	if err := s.db.First(&task, taskID).Error; err != nil {
		return db.Task{}, false
	}
	if task.Status != TaskStatusPendingApproval || task.ApprovalExpiresAt == nil || task.ApprovalExpiresAt.After(now) {
		return db.Task{}, false
	}
	res := s.db.Model(&db.Task{}).
		Where("id = ? AND status = ?", taskID, TaskStatusPendingApproval).
		Updates(map[string]interface{}{"status": "cancelled", "error": approvalExpiredError})
	if res.Error != nil || res.RowsAffected == 0 {
		if res.Error != nil {
			slog.Error("Failed to cancel an expired approval", "task", taskID, "err", res.Error)
		}
		return db.Task{}, false
	}
	s.decPendingTasks(task.AgentID)
	task.Status = "cancelled"
	task.Error = approvalExpiredError
	return task, true
}

// handleRejectTask cancels a pending_approval task so it never reaches the agent.
// POST /tasks/:taskId/reject
func (s *Server) handleRejectTask(c *gin.Context) {
	if !s.requireOperator(c) {
		return
	}

	var taskID uint
	if _, err := fmt.Sscanf(c.Param("taskId"), "%d", &taskID); err != nil {
		respondError(c, http.StatusBadRequest, "invalid task id")
		return
	}

	// Tenant gate (agent-visibility): see handleApproveTask.
	task, ok := s.findVisibleTask(c, taskID)
	if !ok {
		return
	}
	if task.Status != TaskStatusPendingApproval {
		respondError(c, http.StatusBadRequest, fmt.Sprintf("task is %s, cannot reject", task.Status))
		return
	}

	// Snapshot the pre-reject status, then flip to cancelled with a
	// conditional update so a concurrent approve/cancel cannot race us.
	result := s.db.Model(&db.Task{}).
		Where("id = ? AND agent_id = ? AND status = ?", taskID, task.AgentID, TaskStatusPendingApproval).
		Updates(map[string]interface{}{
			"status": "cancelled",
			"error":  "rejected by operator",
		})
	if result.Error != nil {
		slog.Error("Failed to reject task", "task", taskID, "err", result.Error)
		respondError(c, http.StatusInternalServerError, "failed to reject task")
		return
	}
	if result.RowsAffected == 0 {
		currentStatus := TaskStatusPendingApproval
		var fresh db.Task
		if err := s.db.Where("id = ? AND agent_id = ?", taskID, task.AgentID).First(&fresh).Error; err == nil {
			currentStatus = fresh.Status
		}
		respondError(c, http.StatusConflict, fmt.Sprintf("task is now %s, cannot reject", currentStatus))
		return
	}

	task.Status = "cancelled"
	task.Error = "rejected by operator"

	// pending_approval tasks occupy a slot until this terminal transition.
	s.decPendingTasks(task.AgentID)

	slog.Info("Task rejected", "agent_id", task.AgentID, "task", taskID, "type", task.Type)
	s.LogAuditRecord(c, "reject_task", "agent_id", task.AgentID, fmt.Sprintf("Rejected task #%d (%s)", taskID, task.Type), true, nil)
	s.broadcastTaskUpdate(task.AgentID, *task)
	s.postTaskApprovalChat(*task, "approval",
		fmt.Sprintf("Task #%d (%s) on %s rejected by %s", task.ID, task.Type, task.AgentID, s.currentUsername(c)),
		fmt.Sprintf(`{"task_id":%d,"type":%q,"status":"rejected"}`, task.ID, task.Type))
	respond(c, gin.H{"message": "Task rejected"})
}
